            changes: [{
              key: `system.attributes.hp.${hpField}`,
              type: "add",
              value: hpBonus.total
            }],
            disabled: false,
            icon: "icons/magic/life/heart-glowing-red.webp",
            name: _loc("DND5E.SUMMON.FIELDS.bonuses.hp.label")
